const incoming = $input.all();
const flattened = incoming.length === 1 && Array.isArray(incoming[0].json)
  ? incoming[0].json
  : incoming.map((item) => item.json);
const requiredFields = String(
  $('Set Demo Configuration').first().json.required_fields || 'id,name,email'
)
  .split(',')
  .map((field) => field.trim())
  .filter(Boolean);

if (flattened.length === 0) {
  throw new Error('EMPTY_RESPONSE: The upstream API returned no records.');
}

return flattened.map((record, index) => {
  const missing = requiredFields.filter((field) => {
    const value = record?.[field];
    return value === undefined || value === null || String(value).trim() === '';
  });

  return {
    json: {
      source_index: index,
      record_id: record?.id ?? null,
      name: String(record?.name ?? '').trim(),
      email: String(record?.email ?? '').trim().toLowerCase(),
      validation_status: missing.length === 0 ? 'valid' : 'invalid',
      missing_fields: missing,
      source_domain: record?.website ?? null
    }
  };
});

const failure = $input.first().json;
const raw = String(
  failure?.error?.message ||
  failure?.error?.description ||
  failure?.message ||
  'The upstream request failed.'
);

const sanitized = raw
  .replace(/(?:bearer|token|api[_-]?key|password|authorization)\s*[:=]\s*[^\s,;]+/gi, '[credential redacted]')
  .replace(/[?&](?:key|token|api_key|access_token)=[^&\s]+/gi, '?credential=[redacted]')
  .slice(0, 240);

return [{
  json: {
    status: 'failed',
    error: 'upstream_request_failed',
    message: sanitized,
    retryable: true,
    failed_at: new Date().toISOString(),
    next_step: 'Verify the URL and authentication, then run the workflow again.'
  }
}];
